namespace ScreenshotTranslationUiTester;

public static class VisionV2SelfTests
{
    public static int Run(string outputPath)
    {
        var results = new List<string>(); int pass = 0, fail = 0;
        void Test(string name, Action action) { Console.WriteLine($"RUN {name}");try { action(); results.Add($"PASS {name}"); pass++; } catch (Exception ex) { results.Add($"FAIL {name}: {ex.Message}"); fail++; } }
        static void Assert(bool value, string message) { if (!value) throw new InvalidOperationException(message); }
        RecognitionRegion R(string id, RectangleF b, string text = "text") => new() { RegionId = id, Polygon = GeometryV2.RectanglePolygon(b), StructuredText = text, CorrectedText = text };
        RecognitionRegion L(string id, RectangleF b, string text) { var r=R(id,b,text); var block=new OcrEngineBlock { Id=id, RawText=text, CorrectedText=text, BoundingBox=b, Polygon=GeometryV2.RectanglePolygon(b), Enabled=true }; r.SourceBlockIds=[id]; r.DetectedBlocks=[block]; r.SourceLinePolygons=[block.Polygon]; return r; }
        void WithMain(Action<MainForm> action){var path=Path.Combine(Path.GetTempPath(),$"st-main-{Guid.NewGuid():N}.json");ConfigurationManager.Save(path,new ApiSettings{VisualModel=VisualModelKind.Off});try{var main=new MainForm(path);main.Show();action(main);main.Hide();main.Dispose();}finally{if(File.Exists(path))File.Delete(path);if(File.Exists(path+".bak"))File.Delete(path+".bak");}}

        Test("Visual models are independent explicit choices", () => Assert(VisualModelUiMapping.Options.Length == 7 && VisualModelUiMapping.Options.All(x => x.Label.Contains('（') || x.Kind == VisualModelKind.Off), "model labels"));
        Test("Polygon-first geometry", () => Assert(GeometryV2.Bounds([new(0, 0), new(9, 2), new(7, 8)]).Width == 9, "polygon bounds"));
        Test("OCR retained when visual misses", () => { var o = new OcrEngineBlock { Id = "B1", RawText = "hello", BoundingBox = new(10, 10, 50, 20), Enabled = true }; Assert(RegionProposalFusion.Fuse([], [], [o], 1).Single().SourceBlockIds.Contains("B1"), "OCR lost"); });
        Test("Visual-only semantic region retained for crop OCR", () => { var v = new VisualRegion { Polygon = GeometryV2.RectanglePolygon(new(0, 0, 40, 20)), VisualRoleHint = RegionRoleType.Dialogue, Confidence = .9f }; Assert(RegionProposalFusion.Fuse([], [v], [], 1).Single().DetectedBlocks.Count == 0, "visual lost"); });
        Test("Visual-only unknown image region excluded", () => { var v = new VisualRegion { Polygon = GeometryV2.RectanglePolygon(new(0, 0, 40, 20)), VisualRoleHint = RegionRoleType.Unknown, Confidence = .9f }; Assert(RegionProposalFusion.Fuse([], [v], [], 1).Count == 0, "unknown region leaked"); });
        Test("Overlapping sources fuse", () => { var v = new VisualRegion { Polygon = GeometryV2.RectanglePolygon(new(10, 10, 50, 20)), Confidence = .9f }; var o = new OcrEngineBlock { Id = "B", RawText = "x", BoundingBox = new(10, 10, 50, 20), Enabled = true }; Assert(RegionProposalFusion.Fuse([], [v], [o], 1).Count == 1, "not fused"); });
        Test("Far regions do not merge", () => { var a = new OcrEngineBlock { Id = "A", RawText = "a", BoundingBox = new(0, 0, 20, 10), Enabled = true }; var b = new OcrEngineBlock { Id = "B", RawText = "b", BoundingBox = new(200, 200, 20, 10), Enabled = true }; Assert(RegionProposalFusion.Fuse([], [], [a, b], 1).Count == 2, "merged"); });
        Test("Username role", () => Assert(RegionRoleClassifierV2.Classify(R("A", new(0, 0, 50, 10), "@imsober"), []).Role == RegionRoleType.CharacterName, "role"));
        Test("Metadata role", () => Assert(RegionRoleClassifierV2.Classify(R("A", new(0, 0, 50, 10), "26K views"), []).Role == RegionRoleType.Metadata, "role"));
        Test("Chinese relative-time metadata role", () => Assert(RegionRoleClassifierV2.Classify(R("A", new(0, 0, 80, 10), "\u5927\u7ea6 2 \u5c0f\u65f6\u524d"), []).Role == RegionRoleType.Metadata, "role"));
        Test("Chinese message-count metadata role", () => Assert(RegionRoleClassifierV2.Classify(R("A", new(0, 0, 80, 10), "43 \u6761\u6d88\u606f"), []).Role == RegionRoleType.Metadata, "role"));
        Test("Game button role", () => Assert(RegionRoleClassifierV2.Classify(R("A", new(0, 0, 50, 10), "Continue"), []).Role == RegionRoleType.Button, "role"));
        Test("Game choice role", () => Assert(RegionRoleClassifierV2.Classify(R("A", new(0, 0, 50, 10), "Tell the truth"), []).Role == RegionRoleType.Choice, "role"));
        Test("Top large card heading role", () => { var title=R("T",new(10,5,300,42),"The Mouth in the Hole of the wall"); var body=R("B",new(160,70,300,24),"You moved into a cheap apartment"); Assert(RegionRoleClassifierV2.Classify(title,[title,body]).Role==RegionRoleType.Title,"role"); });
        Test("Narrow card seven wrapped lines become one semantic region", () => { var lines=new[]{"Your childhood","best friend","disappeared for","years... now she's","back as one of","Japan's biggest","celebrities."}.Select((x,i)=>L($"L{i}",new(100,100+i*24,180,20),x)).ToArray(); var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==1 && grouped[0].SourceBlockIds.Count==7,"under-grouped"); });
        Test("Game name remains separate from wrapped dialogue", () => { var lines=new[]{L("N",new(20,10,70,20),"Alice"),L("D1",new(20,40,330,20),"\"Well well well, I see you haven't"),L("D2",new(20,64,340,20),"changed at all since high school. Still a"),L("D3",new(20,88,100,20),"wimp.\"")}; var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==2 && grouped[1].SourceBlockIds.Count==3,"dialogue grouping"); var role=RegionRoleClassifierV2.Classify(grouped[1],grouped); Assert(role.Role==RegionRoleType.Dialogue,"dialogue role"); });
        Test("Rapid-only large heading stays separate from smaller caption", () => { var lines=new[]{L("T",new(68,67,284,28),"Bitchy Ex | April Torres"),L("C",new(61,116,179,18),"Your bitchy ex-gf is back in your life")}; var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==2,"heading and caption merged without PP-S"); });
        Test("April paragraph gaps prevent page over-grouping", () => { var lines=new[]{L("T",new(20,10,80,22),"April"),L("H",new(20,45,350,20),"18:30 | August 01, 2026 | April's Dorm Room"),L("A1",new(20,80,420,20),"April somehow convinced Yan Yi"),L("A2",new(20,104,430,20),"to stay for the evening and talk."),L("D1",new(20,160,400,20),"\"Fuuuck...\" she breathed"),L("D2",new(20,184,380,20),"and closed her eyes."),L("B1",new(20,240,350,20),"And she was right about one thing."),L("B2",new(20,264,330,20),"Nothing would be the same.")}; var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==5 && grouped.Count(x=>x.SourceBlockIds.Count==2)==3,"paragraph boundaries"); });
        Test("Magazine distant columns remain isolated", () => { var lines=new[]{L("A1",new(10,100,150,20),"Left column begins"),L("A2",new(10,124,150,20),"and continues here."),L("B1",new(350,100,150,20),"Right column begins"),L("B2",new(350,124,150,20),"and continues here.")}; var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==2 && grouped.All(x=>x.SourceBlockIds.Count==2),"cross-column merge"); });
        Test("Magazine vertical decorative title merges", () => { var lines=new[]{L("T",new(20,100,90,55),"TIME"),L("I",new(20,180,70,55),"IS"),L("N",new(20,260,100,55),"NOW")}; var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==1&&grouped[0].SourceBlockIds.Count==3,"decorative fragmentation"); });
        Test("Local paragraph gap splits two complete prose blocks", () => { var lines=new[]{L("A1",new(20,10,420,20),"Well, well, well... she opened the door,"),L("A2",new(20,34,430,20),"and looked at him."),L("A3",new(20,58,400,20),"Look who actually showed up."),L("B1",new(20,96,430,20),"She stepped back and opened the door wider,"),L("B2",new(20,120,420,20),"then crooked a finger at him."),L("B3",new(20,144,390,20),"Get in before someone sees me.")}; var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==2&&grouped.All(x=>x.SourceBlockIds.Count==3),"paragraph over-grouping"); });
        Test("Eight ordinary wrapped lines remain one paragraph", () => { var lines=Enumerable.Range(0,8).Select(i=>L($"W{i}",new(20,10+i*24,420-(i%3)*20,20),i==7?"the final wrapped line.":$"ordinary wrapped content line {i}")).ToArray(); var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==1&&grouped[0].SourceBlockIds.Count==8,"wrapped lines split"); });
        Test("Narration and quote in one visual paragraph stay together", () => { var lines=new[]{L("N1",new(20,10,420,20),"She looked at him. \"Come here,\""),L("N2",new(20,34,360,20),"she said without looking away.")}; Assert(SemanticRegionGrouperV2.Group(lines,1).Count==1,"quote-only split"); });
        Test("Large gap separates dialogue and narration paragraphs", () => { var lines=new[]{L("D1",new(20,10,420,20),"\"What do you think?\" she asked."),L("D2",new(20,34,380,20),"He did not answer her."),L("N1",new(20,78,420,20),"Once he was inside, she closed the door."),L("N2",new(20,102,380,20),"The room became quiet.")}; var grouped=SemanticRegionGrouperV2.Group(lines,1); Assert(grouped.Count==2,"dialogue boundary merged"); });
        Test("Semantic region preserves source line polygons", () => { var grouped=SemanticRegionGrouperV2.Group([L("A",new(0,0,80,10),"wrapped line"),L("B",new(0,12,80,10),"continues.")],1).Single(); Assert(grouped.SourceLinePolygons.Count==2 && grouped.SourceBlockIds.SequenceEqual(["A","B"]),"line geometry lost"); });
        Test("Safe target never unions incompatible roles",()=>{var a=L("TITLE",new(10,10,260,22),"Card title");a.RoleType=RegionRoleType.Title;var b=L("QUOTE",new(150,36,180,20),"\"Dialogue\"");b.RoleType=RegionRoleType.Dialogue;Assert(SemanticRegionGrouperV2.Group([a,b],1).Count==2,"incompatible roles unioned");});
        Test("Safe target rejects disconnected geometry union",()=>{var r=L("A",new(10,10,100,20),"first");r.SourceBlockIds.Add("B");r.SourceLinePolygons.Add(GeometryV2.RectanglePolygon(new(300,120,100,20)));r.DetectedBlocks.Add(new OcrEngineBlock{Id="B",RawText="second",CorrectedText="second",BoundingBox=new(300,120,100,20),Polygon=GeometryV2.RectanglePolygon(new(300,120,100,20)),Enabled=true});r.TranslationText="完整译文";Assert(SafeLayoutTargetPlanner.Plan(r).Status==SafeLayoutTargetStatus.UnsafeStructureTarget,"disconnected union accepted");});
        Test("Safe target rejects image exclusion intrusion",()=>{var r=L("A",new(10,10,300,30),"heading");r.RendererTargetRegion=new(10,10,300,100);var exclusion=new RectangleF(20,45,140,60);r.LayoutExclusionPolygons=[GeometryV2.RectanglePolygon(exclusion)];var d=SafeLayoutTargetPlanner.Plan(r);Assert(d.Status==SafeLayoutTargetStatus.Safe&&d.Targets.All(x=>RectangleF.Intersect(x,exclusion).IsEmpty),"image intrusion accepted");});
        Test("Safe target keeps adjacent multiline paragraph",()=>{var lines=Enumerable.Range(0,5).Select(i=>{var r=L($"P{i}",new(20,20+i*24,300,20),$"paragraph line {i}");r.RoleType=RegionRoleType.BodyParagraph;return r;}).ToArray();var grouped=SemanticRegionGrouperV2.Group(lines,1);Assert(grouped.Count==1&&SafeLayoutTargetPlanner.Plan(grouped[0]).Status==SafeLayoutTargetStatus.Safe,"normal paragraph fragmented");});
        Test("Safe target leaves translation characters unchanged",()=>{using var b=new Bitmap(320,100);var r=L("A",new(10,10,280,70),"source");r.TranslationText="逐字符 ABC 123，不得改变。";var before=r.TranslationText;var x=RegionRendererV2.Render(b,[r],new RenderSettings());using var image=x.Bitmap;Assert(r.TranslationText==before&&string.Concat(x.Diagnostics!.Single().RenderedLines.Select(y=>y.Text))==before,"translation content changed");});
        Test("Disconnected target never guesses segment mapping",()=>{var r=L("A",new(10,10,100,20),"first");r.SourceBlockIds.Add("B");r.SourceLinePolygons.Add(GeometryV2.RectanglePolygon(new(250,90,100,20)));r.TranslationText="only whole translation";var d=SafeLayoutTargetPlanner.Plan(r);Assert(!d.HasReliableSegmentMapping&&d.Targets.Count==0,"guessed segment mapping");});
        Test("Unsafe target uses explicit translation-first fallback",()=>{using var b=new Bitmap(360,140);using(var g=Graphics.FromImage(b))g.Clear(Color.FromArgb(17,33,55));var r=L("A",new(10,10,100,20),"first");r.SourceBlockIds.Add("B");r.SourceLinePolygons.Add(GeometryV2.RectanglePolygon(new(250,90,100,20)));r.DetectedBlocks.Add(new OcrEngineBlock{Id="B",RawText="second",BoundingBox=new(250,90,100,20),Polygon=GeometryV2.RectanglePolygon(new(250,90,100,20)),Enabled=true});r.TranslationText="译文";var x=RegionRendererV2.Render(b,[r],new RenderSettings());using var image=x.Bitmap;var d=x.Diagnostics!.Single();Assert(d.FallbackAttempted&&d.FallbackRendered&&d.AtomicRegionCommitted&&string.Concat(d.RenderedLines.Select(y=>y.Text))==r.TranslationText,"unsafe target did not use complete fallback");});
        Test("Safe planning preserves SourceRegionRect",()=>{var r=L("A",new(12,14,120,24),"source");var original=r.SourceImageRegion=r.BoundingBox;r.RendererTargetRegion=new(5,5,200,60);_ = SafeLayoutTargetPlanner.Plan(r);Assert(r.SourceImageRegion==original&&r.BoundingBox==original,"source rect mutated");});
        Test("Geometry islands retain Region and SourceBlock trace",()=>{var a=L("A",new(10,10,100,20),"one");a.SourceBlockIds.Add("B");a.SourceLinePolygons.Add(GeometryV2.RectanglePolygon(new(260,80,100,20)));var d=SafeLayoutTargetPlanner.Plan(a);Assert(d.Islands.SelectMany(x=>x.SourceBlockIds).Order().SequenceEqual(["A","B"]),"trace ids lost");});
        Test("Failed structure validation commits fallback atomically",()=>{using var b=new Bitmap(260,100);using(var g=Graphics.FromImage(b)){g.Clear(Color.Navy);g.FillRectangle(Brushes.Gold,20,20,30,30);}var r=L("A",new(10,10,80,20),"first");r.SourceBlockIds.Add("B");r.SourceLinePolygons.Add(GeometryV2.RectanglePolygon(new(180,70,60,20)));r.TranslationText="中文";var x=RegionRendererV2.Render(b,[r],new RenderSettings{BackgroundStrategy=TranslationOverlayBackgroundStyle.Solid});using var image=x.Bitmap;var d=x.Diagnostics!.Single();Assert(d.FallbackRendered&&d.AtomicRegionCommitted&&d.TextDrawCount==1,"fallback transaction was not atomic");});
        Test("Phase 1.1 original overlap preserved",()=>{var r=L("R001",new(51,19,518,29),"title");r.RoleType=RegionRoleType.Title;var exclusion=new RectangleF(21.93f,33.03f,215.45f,261.91f);r.LayoutExclusionPolygons=[GeometryV2.RectanglePolygon(exclusion)];var d=SafeLayoutTargetPlanner.Plan(r);var m=SafeLayoutTargetPlanner.AnalyzeImageIntrusion(d.Targets.Single(),[r.BoundingBox],exclusion);Assert(d.Status==SafeLayoutTargetStatus.Safe&&m.SourceImageOverlapArea>0&&m.AddedIntrusionArea==0,"legitimate overlap removed or rejected");});
        Test("Phase 1.1 added image intrusion is zero",()=>{var r=L("A",new(10,10,100,20),"line one");r.RoleType=RegionRoleType.BodyParagraph;var b=L("B",new(10,50,100,20),"line two");b.RoleType=RegionRoleType.BodyParagraph;r.SourceBlockIds.AddRange(b.SourceBlockIds);r.SourceLinePolygons.AddRange(b.SourceLinePolygons);r.DetectedBlocks.AddRange(b.DetectedBlocks);var exclusion=new RectangleF(10,30,100,20);r.LayoutExclusionPolygons=[GeometryV2.RectanglePolygon(exclusion)];Assert(SafeLayoutTargetPlanner.Plan(r).Status==SafeLayoutTargetStatus.UnsafeStructureTarget,"new intrusion accepted");});
        Test("Phase 1.1 dialogue image intrusion is zero",()=>{var r=L("R002",new(257,50,309,70),"dialogue");r.RoleType=RegionRoleType.Dialogue;var exclusion=new RectangleF(21.93f,33.03f,215.45f,261.91f);r.LayoutExclusionPolygons=[GeometryV2.RectanglePolygon(exclusion)];var d=SafeLayoutTargetPlanner.Plan(r);var m=SafeLayoutTargetPlanner.AnalyzeImageIntrusion(d.Targets.Single(),[r.BoundingBox],exclusion);Assert(d.Status==SafeLayoutTargetStatus.Safe&&m.NewTargetImageOverlapArea==0&&m.AddedIntrusionArea==0,"dialogue entered image");});
        Test("Phase 1.1 independent TranslationUnits share one batch",()=>{var units=new[]{new TranslationUnitV2("GRP001",["T"],RegionRoleType.Title,"title",1,false),new TranslationUnitV2("GRP002",["D"],RegionRoleType.Dialogue,"dialogue",2,false),new TranslationUnitV2("GRP003",["H"],RegionRoleType.Header,"header",3,false)};var items=units.Select(x=>new TranslationItem(x.Id,x.Text,x.RoleType switch{RegionRoleType.Title=>StructuredTextRole.Title,RegionRoleType.Dialogue=>StructuredTextRole.Dialogue,RegionRoleType.Header=>StructuredTextRole.Header,_=>StructuredTextRole.Unknown})).ToArray();var json=TranslationService.BuildStructuredInputForTest(items);using var doc=System.Text.Json.JsonDocument.Parse(json);Assert(doc.RootElement.GetArrayLength()==3&&doc.RootElement.EnumerateArray().Select(x=>x.GetProperty("id").GetString()).SequenceEqual(["GRP001","GRP002","GRP003"]),"units not serialized in one batch");});
        Test("Phase 1.1 renderer guess split is false",()=>{var r=L("A",new(10,10,80,20),"one");r.SourceBlockIds.Add("B");r.SourceLinePolygons.Add(GeometryV2.RectanglePolygon(new(220,80,80,20)));r.TranslationText="one whole translation";var d=SafeLayoutTargetPlanner.Plan(r);Assert(d.Status==SafeLayoutTargetStatus.UnsafeStructureTarget&&d.Targets.Count==0&&!d.HasReliableSegmentMapping,"renderer split was guessed");});
        Test("Phase 1.1 unsafe mapping keeps full translation in fallback",()=>{using var source=new Bitmap(320,120);using(var g=Graphics.FromImage(source)){g.Clear(Color.FromArgb(31,47,63));g.FillEllipse(Brushes.Orange,20,20,45,45);}var r=L("A",new(10,10,80,20),"one");r.SourceBlockIds.Add("B");r.SourceLinePolygons.Add(GeometryV2.RectanglePolygon(new(220,80,80,20)));r.TranslationText="translation";var rendered=RegionRendererV2.Render(source,[r],new RenderSettings());using var output=rendered.Bitmap;var d=rendered.Diagnostics!.Single();Assert(d.FallbackRendered&&string.Concat(d.RenderedLines.Select(x=>x.Text))==r.TranslationText,"unsafe mapping lost translation");});
        Test("Preview region debug labels default hidden", () => { using var image=new Bitmap(160,80); using var form=new PreviewForm(image,PreviewMode.OcrOnly,new ApiSettings { VisualModel=VisualModelKind.Off },new OcrService(),new TranslationService()); Assert(!form.RegionLabelsVisibleForSmoke,"labels visible"); });
        Test("Fresh Preview has every debug layer off", () => { using var image=new Bitmap(160,80); using var form=new PreviewForm(image,PreviewMode.OcrOnly,new ApiSettings { VisualModel=VisualModelKind.Off },new OcrService(),new TranslationService()); Assert(form.VisibleV2LayerCountForSmoke==0,"debug layer enabled"); });
        Test("MainNavigation 20 loops has no blank page",()=>WithMain(main=>{for(var loop=0;loop<20;loop++)foreach(var name in MainForm.MainPageNamesForSmoke)Assert(main.NavigateForSmoke(name),$"blank {name} loop {loop}");Assert(main.MainHostControlCountForSmoke==3,"host lost pages");}));
        Test("MainNavigation random 100 has no blank page",()=>WithMain(main=>{var random=new Random(424);for(var i=0;i<100;i++){var name=MainForm.MainPageNamesForSmoke[random.Next(MainForm.MainPageNamesForSmoke.Length)];Assert(main.NavigateForSmoke(name),$"blank random {i} {name}");}}));
        Test("Settings tabs 30 loops have content",()=>WithMain(main=>{for(var loop=0;loop<30;loop++)for(var i=0;i<main.SettingsTabCountForSmoke;i++)Assert(main.SettingsTabAliveForSmoke(i),$"blank settings tab {i} loop {loop}");}));
        Test("Settings leave and return 20 loops remains alive",()=>WithMain(main=>{for(var i=0;i<20;i++){Assert(main.NavigateForSmoke("设置"),"settings blank");Assert(main.SettingsTabAliveForSmoke(i%main.SettingsTabCountForSmoke),"tab blank");Assert(main.NavigateForSmoke("主页"),"home page blank");}}));
        Test("After Preview close all main pages remain alive",()=>WithMain(main=>{using var image=new Bitmap(180,90);using var preview=main.OpenPreviewForSmoke(image);preview.Close();foreach(var name in MainForm.MainPageNamesForSmoke)Assert(main.NavigateForSmoke(name),$"after preview blank {name}");}));
        Test("After Settings save current page remains alive",()=>WithMain(main=>{Assert(main.NavigateForSmoke("设置"),"settings blank before save");main.SaveSettingsForSmoke();Assert(main.NavigateForSmoke("设置")&&main.SettingsTabAliveForSmoke(0),"settings blank after save");}));
        Test("After appearance refresh every page remains alive",()=>WithMain(main=>{main.RefreshAppearanceForSmoke();foreach(var name in MainForm.MainPageNamesForSmoke)Assert(main.NavigateForSmoke(name),$"appearance blank {name}");}));
        Test("Minimize restore preserves page host",()=>WithMain(main=>{main.WindowState=FormWindowState.Minimized;main.WindowState=FormWindowState.Normal;Assert(main.NavigateForSmoke("设置")&&main.SettingsTabAliveForSmoke(4),"restore blank");}));
        Test("Default translated shows translated when render completes",()=>{using var source=new Bitmap(200,100);using var translated=new Bitmap(200,100);using var form=new PreviewForm(source,PreviewMode.OcrOnly,new ApiSettings{PreviewDefaultImage=PreviewDefaultImage.Translated,VisualModel=VisualModelKind.Off},new OcrService(),new TranslationService());Assert(form.ImageViewForSmoke==ImageViewMode.Translated&&form.DisplayedImageViewForSmoke==ImageViewMode.Original&&form.ImageModeTextForSmoke.Contains("生成中"),"initial fallback state");form.SetTranslatedDisplayForSmoke(translated);Assert(form.DisplayedImageViewForSmoke==ImageViewMode.Translated&&form.ImageModeTextForSmoke=="译图（实验）","render completion did not switch");});
        Test("Default original stays original after render",()=>{using var source=new Bitmap(200,100);using var translated=new Bitmap(200,100);using var form=new PreviewForm(source,PreviewMode.OcrOnly,new ApiSettings{PreviewDefaultImage=PreviewDefaultImage.Original,VisualModel=VisualModelKind.Off},new OcrService(),new TranslationService());form.SetTranslatedDisplayForSmoke(translated);Assert(form.ImageViewForSmoke==ImageViewMode.Original&&form.DisplayedImageViewForSmoke==ImageViewMode.Original,"default original changed");});
        Test("User original during translation remains original",()=>{using var source=new Bitmap(200,100);using var translated=new Bitmap(200,100);using var form=new PreviewForm(source,PreviewMode.OcrOnly,new ApiSettings{PreviewDefaultImage=PreviewDefaultImage.Translated,VisualModel=VisualModelKind.Off},new OcrService(),new TranslationService());form.SetPreviewSelectionForSmoke(OcrEngineKind.Rapid,ImageViewMode.Original,TextViewMode.Organized);form.SetTranslatedDisplayForSmoke(translated);Assert(form.DisplayedImageViewForSmoke==ImageViewMode.Original,"user original overridden");});
        Test("User translated during translation displays when ready",()=>{using var source=new Bitmap(200,100);using var translated=new Bitmap(200,100);using var form=new PreviewForm(source,PreviewMode.OcrOnly,new ApiSettings{PreviewDefaultImage=PreviewDefaultImage.Original,VisualModel=VisualModelKind.Off},new OcrService(),new TranslationService());form.SetPreviewSelectionForSmoke(OcrEngineKind.Rapid,ImageViewMode.Translated,TextViewMode.Translation);Assert(form.DisplayedImageViewForSmoke==ImageViewMode.Original&&form.ImageModeTextForSmoke.Contains("生成中"),"temporary fallback unclear");form.SetTranslatedDisplayForSmoke(translated);Assert(form.DisplayedImageViewForSmoke==ImageViewMode.Translated,"user translated not honored");});
        Test("Retranslate preserves translated preferred mode",()=>{using var source=new Bitmap(200,100);using var first=new Bitmap(200,100);using var second=new Bitmap(200,100);using var form=new PreviewForm(source,PreviewMode.OcrOnly,new ApiSettings{PreviewDefaultImage=PreviewDefaultImage.Translated,VisualModel=VisualModelKind.Off},new OcrService(),new TranslationService());form.SetTranslatedDisplayForSmoke(first);form.SetTranslatedDisplayForSmoke(null,"Retranslation");form.SetTranslatedDisplayForSmoke(second,"RendererCompleted");Assert(form.ImageViewForSmoke==ImageViewMode.Translated&&form.DisplayedImageViewForSmoke==ImageViewMode.Translated,"retranslation reset view");});
        Test("OCR rerun returns to translated preferred mode",()=>{using var source=new Bitmap(200,100);using var translated=new Bitmap(200,100);using var form=new PreviewForm(source,PreviewMode.OcrOnly,new ApiSettings{PreviewDefaultImage=PreviewDefaultImage.Translated,VisualModel=VisualModelKind.Off},new OcrService(),new TranslationService());form.SetTranslatedDisplayForSmoke(null,"OCRRerun");form.SetTranslatedDisplayForSmoke(translated,"RendererCompleted");Assert(form.DisplayedImageViewForSmoke==ImageViewMode.Translated,"OCR rerun reset view");});
        Test("Appearance refresh keeps translated mode",()=>{using var source=new Bitmap(200,100);using var translated=new Bitmap(200,100);using var form=new PreviewForm(source,PreviewMode.OcrOnly,new ApiSettings{PreviewDefaultImage=PreviewDefaultImage.Translated,VisualModel=VisualModelKind.Off},new OcrService(),new TranslationService());form.SetTranslatedDisplayForSmoke(translated);form.ApplyAppearanceSettings(new ApiSettings{OverlayBackgroundStyle=TranslationOverlayBackgroundStyle.Solid});Assert(form.DisplayedImageViewForSmoke==ImageViewMode.Translated,"appearance reset view");});
