        Test("V2 missing=GRP001 targeted recovery", () =>
        {
            static string Envelope(string content) => System.Text.Json.JsonSerializer.Serialize(new { choices = new[] { new { message = new { content } } } });
            var regions = new[] { R("R1", new(0,0,20,10), "April"), R("R2", new(0,20,30,10), "Hello") };
            var units = TranslationUnitBuilderV2.Build(regions);
            var items = units.Select(x => new TranslationItem(x.Id, x.Text, x.RoleType == RegionRoleType.CharacterName ? StructuredTextRole.CharacterName : StructuredTextRole.Dialogue)).ToArray();
            var recovered = TranslationService.RecoverMissingGroupsForTest(items, Envelope("{\"GRP002\":\"你好\"}"), Envelope("{\"GRP001\":\"April\"}"), out var recoveryIds);
            Assert(recoveryIds.SequenceEqual(["GRP001"]) && recovered.Translations.Count == 2 && recovered.RequestCount == 2, "targeted recovery was not isolated");
        });
        Test("V2 recovery still missing fails", () => { static string E(string c) => System.Text.Json.JsonSerializer.Serialize(new { choices = new[] { new { message = new { content = c } } } }); try { TranslationService.RecoverMissingGroupsForTest([new("GRP001","a"),new("GRP002","b")], E("{\"GRP002\":\"B\"}"), E("{}"), out _); throw new Exception("accepted"); } catch (BatchJsonException) { } });
