        Test("Readable fallback commits full translation with mask-local cleanup", () => { using var b=new Bitmap(360,110);using(var g=Graphics.FromImage(b)){g.Clear(Color.FromArgb(35,45,55));using var f=new Font("Arial",18);g.DrawString("SOURCE GLYPHS",f,Brushes.White,new PointF(12,35));}var r=L("FB",new(10,20,210,55),"SOURCE GLYPHS");r.RoleType=RegionRoleType.CharacterName;r.SourceLinePolygons=[GeometryV2.RectanglePolygon(new RectangleF(10,20,210,55))];r.TranslationText="这是必须完整显示的较长译文";var neighbor=L("N",new(285,20,60,55),"KEEP");neighbor.PreserveOriginal=true;neighbor.TranslationText="KEEP";var x=RegionRendererV2.Render(b,[r,neighbor],new RenderSettings{Outline=false,Shadow=false,MinFontSize=10});using var image=x.Bitmap;var d=x.Diagnostics!.Single(v=>v.RegionId=="FB");var drawn=string.Concat(d.RenderedLines.Select(v=>v.Text));Assert(d.AtomicRegionCommitted&&d.DecisionCode=="VisibleTranslationCommitted"&&d.Alpha==0&&drawn==r.TranslationText&&d.Coverage.All(v=>v.Masked&&v.Decision=="ReadableFallbackCleanupMask")&&RectangleF.Intersect(d.RenderBounds,neighbor.BoundingBox).IsEmpty,$"fallback did not provide an ownership-safe visible commit: status={d.RenderStatus}, code={d.DecisionCode}, alpha={d.Alpha}, drawn={drawn.Length}/{r.TranslationText.Length}, bounds={d.RenderBounds}"); });
