        Test("Preserved username has explicit disposition", () => { var r=L("U",new(5,5,80,15),"@imsober");r.PreserveOriginal=true;var regions=new List<RecognitionRegion>{r};var c=RecognitionCoverageFinalizer.Finalize(regions,r.DetectedBlocks,new(100,40),1).Coverage.Single();Assert(c.Disposition==SourceLineDisposition.PreserveOriginal,"preserve missing"); });
