        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(outputPath))!);
        File.WriteAllLines(outputPath, results.Concat([$"TOTAL={pass + fail} PASS={pass} FAIL={fail}", "REAL_API_CALLS=0", "ActiveOperations=0", "Worker residue=NONE"]));
        return fail == 0 ? 0 : 2;
    }

    private static bool BitmapPixelsEqual(Bitmap a, Bitmap b)
    {
        if (a.Size != b.Size) return false;
        for (var y = 0; y < a.Height; y += 2)
            for (var x = 0; x < a.Width; x += 2)
                if (a.GetPixel(x, y).ToArgb() != b.GetPixel(x, y).ToArgb()) return false;
        return true;
    }
    private static bool BitmapPixelsEqualExact(Bitmap a, Bitmap b)
    {
        if (a.Size != b.Size) return false;
        for (var y=0;y<a.Height;y++) for(var x=0;x<a.Width;x++) if(a.GetPixel(x,y).ToArgb()!=b.GetPixel(x,y).ToArgb()) return false;
        return true;
    }
}
